class Solution {
public:
    long long totalCost(std::vector<int>& costs, int k, int candidates) {
        int n = costs.size();
        std::priority_queue<int, std::vector<int>, std::greater<int>> h1, h2;
        int l = 0, r = n - 1;
        for (int i = 0; i < candidates && l <= r; ++i) h1.push(costs[l++]);
        for (int i = 0; i < candidates && l <= r; ++i) h2.push(costs[r--]);
        long long ans = 0;
        for (int step = 0; step < k; ++step) {
            if (h2.empty() || (!h1.empty() && h1.top() <= h2.top())) {
                ans += h1.top();
                h1.pop();
                if (l <= r) h1.push(costs[l++]);
            } else {
                ans += h2.top();
                h2.pop();
                if (l <= r) h2.push(costs[r--]);
            }
        }
        return ans;
    }
};

class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        java.util.PriorityQueue<Integer> h1 = new java.util.PriorityQueue<>();
        java.util.PriorityQueue<Integer> h2 = new java.util.PriorityQueue<>();
        int l = 0, r = n - 1;
        for (int i = 0; i < candidates && l <= r; i++) h1.offer(costs[l++]);
        for (int i = 0; i < candidates && l <= r; i++) h2.offer(costs[r--]);
        long ans = 0;
        for (int step = 0; step < k; step++) {
            if (h2.isEmpty() || (!h1.isEmpty() && h1.peek() <= h2.peek())) {
                ans += h1.poll();
                if (l <= r) h1.offer(costs[l++]);
            } else {
                ans += h2.poll();
                if (l <= r) h2.offer(costs[r--]);
            }
        }
        return ans;
    }
}

var totalCost = function(costs, k, candidates) {
    class MinHeap {
        constructor() { this.heap = []; }
        push(val) {
            this.heap.push(val);
            this._bubbleUp(this.heap.length - 1);
        }
        pop() {
            if (this.heap.length === 0) return null;
            const top = this.heap[0];
            const bottom = this.heap.pop();
            if (this.heap.length > 0) {
                this.heap[0] = bottom;
                this._bubbleDown(0);
            }
            return top;
        }
        peek() { return this.heap.length > 0 ? this.heap[0] : null; }
        size() { return this.heap.length; }
        _bubbleUp(idx) {
            while (idx > 0) {
                const parent = Math.floor((idx - 1) / 2);
                if (this.heap[idx] < this.heap[parent]) {
                    [this.heap[idx], this.heap[parent]] = [this.heap[parent], this.heap[idx]];
                    idx = parent;
                } else break;
            }
        }
        _bubbleDown(idx) {
            const len = this.heap.length;
            while (true) {
                let smallest = idx;
                const left = 2 * idx + 1;
                const right = 2 * idx + 2;
                if (left < len && this.heap[left] < this.heap[smallest]) smallest = left;
                if (right < len && this.heap[right] < this.heap[smallest]) smallest = right;
                if (smallest !== idx) {
                    [this.heap[idx], this.heap[smallest]] = [this.heap[smallest], this.heap[idx]];
                    idx = smallest;
                } else break;
            }
        }
    }
    const n = costs.length;
    const h1 = new MinHeap();
    const h2 = new MinHeap();
    let l = 0, r = n - 1;
    for (let i = 0; i < candidates && l <= r; i++) h1.push(costs[l++]);
    for (let i = 0; i < candidates && l <= r; i++) h2.push(costs[r--]);
    let ans = 0;
    for (let step = 0; step < k; step++) {
        if (h2.size() === 0 || (h1.size() > 0 && h1.peek() <= h2.peek())) {
            ans += h1.pop();
            if (l <= r) h1.push(costs[l++]);
        } else {
            ans += h2.pop();
            if (l <= r) h2.push(costs[r--]);
        }
    }
    return ans;
};
